window.MOTIF_CATALOG_CHUNKS[5]={"cards":[{"id":"ML-T00539","row_version":4,"title":"클래식 음악","original":"Classical Music","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"서양의 오래된 공연·작곡 전통을 중심으로 묶어 부르는 음악 영역. 작품에서는 연주와 감상의 공간이 인물의 취향이나 시대 분위기를 나타낸다. 클래식 감상을 허세나 지루함으로 처리하는 묘사는 클래식 음악을 지루하게 묘사하기의 관습이다. 음악을 직접 들으며 선입견이 깨지는 이야기는 클래식 음악의 매력 재발견으로 이어진다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"클래식 음악","entry_url":"cards/ML-T00539/index.html"},{"id":"ML-T00540","row_version":2,"title":"현대 예술음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"현대 예술음악은 주로 20세기 이후의 작곡 전통에서 새로운 음색과 형식, 조성·리듬의 실험을 중시하는 음악이다. 단지 최근에 만들어졌거나 전자 악기를 쓴 음악을 뜻하지 않으므로 작곡의 맥락과 실험적 구성 원리를 기준으로 삼는다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"현대 예술음악","entry_url":"cards/ML-T00540/index.html"},{"id":"ML-T00541","row_version":3,"title":"전통 민요","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"전통 민요는 공동체의 생활과 기억 속에서 전승되며 구전과 변형을 거쳐 불려 온 노래다. 옛 분위기를 재현한 창작곡과 혼동하지 말고 특정 지역이나 집단의 전승·가창 맥락이 확인되는지 본다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"전통 민요","entry_url":"cards/ML-T00541/index.html"},{"id":"ML-T00542","row_version":3,"title":"판소리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"판소리는 한 명의 소리꾼이 노래와 말, 몸짓으로 서사를 펼치고 고수가 북으로 장단을 받치는 한국의 음악극 형식이다. 전통 창법을 사용한 노래 일반과 구별해 소리·아니리·발림의 서사적 결합과 고수의 역할을 살핀다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"판소리","entry_url":"cards/ML-T00542/index.html"},{"id":"ML-T00543","row_version":2,"title":"정악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"정악은 궁중과 선비 문화 등에서 연주된 한국 전통음악의 한 갈래로, 절제된 표현과 정돈된 선율·장단을 중시한다. 궁중에서 연주된 모든 음악이나 느린 기악곡을 뜻하지 않으므로 해당 음악 전통의 형식과 연주 관습을 확인한다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"정악","entry_url":"cards/ML-T00543/index.html"},{"id":"ML-T00544","row_version":3,"title":"농악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"농악은 농촌 공동체의 굿과 노동, 축원과 놀이에 연결되어 꽹과리·장구·북·징 등의 타악 연주와 춤·행렬이 어우러지는 공연 전통이다. 타악기 합주만을 뜻하지 않으며 공동체적 기능과 연행 요소가 함께 나타나는지 살핀다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"농악","entry_url":"cards/ML-T00544/index.html"},{"id":"ML-T00545","row_version":2,"title":"성가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"성가는 종교 의식이나 예배에서 부르도록 마련된 노래와 합창을 가리키며, 전례의 언어와 음악 관습에 맞춰 전승되기도 한다. 종교적 주제를 다룬 대중가요와 구별해 실제 예배·의례의 용도나 성가 전통과의 관계를 기준으로 삼는다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"성가","entry_url":"cards/ML-T00545/index.html"},{"id":"ML-T00546","row_version":2,"title":"가스펠","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"가스펠은 기독교 신앙과 예배·전도 맥락에서 발전한 음악으로, 강한 보컬과 합창, 가스펠 특유의 화성과 리듬을 자주 활용한다. 종교적 가사를 가진 모든 음악과 같지 않으므로 형식과 연주 관습이 가스펠 전통에 닿아 있는지 살핀다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"가스펠","entry_url":"cards/ML-T00546/index.html"},{"id":"ML-T00547","row_version":2,"title":"의례음악","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":"tag","parent_id":"ML-T00538","tag_path":[],"summary":"의례음악은 종교적·사회적 의례의 순서와 기능에 맞춰 연주되거나 노래되는 음악이다. 의례를 배경으로 삼은 감상용 창작곡과 구별해 음악이 실제 의식의 진행이나 참여를 위해 쓰이는지 확인한다.","accent":"#8A687E","tab":"#7F9C91","facet":"장르","bookmark":"의례음악","entry_url":"cards/ML-T00547/index.html"},{"id":"ML-T00548","row_version":3,"title":"적용 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"모티프가 작품의 어느 크기와 범위에서 나타나는지를 가리킨다. 적용할 때는 표현 매체나 작품 길이가 아니라 실제로 확인되는 최소·최대 범위를 기준으로 삼는다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"적용 단위","entry_url":"cards/ML-T00548/index.html"},{"id":"ML-T00549","row_version":3,"title":"단어 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"낱말 하나의 의미나 소리, 표기가 반복되거나 변형되어 의미를 만드는 경우다. 단어가 문장이나 장면의 일부로 등장하는 데 그치면 단어 단위로 분류하지 않는다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"단어 단위","entry_url":"cards/ML-T00549/index.html"},{"id":"ML-T00550","row_version":2,"title":"문장 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"한 문장이 의미·리듬·구조를 이루는 핵심 표현 단위로 기능한다. 문장 안의 낱말만 두드러지는지, 문장 전체의 구성이나 반복이 작동하는지 구분한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"문장 단위","entry_url":"cards/ML-T00550/index.html"},{"id":"ML-T00551","row_version":4,"title":"이미지 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"정지 화면이나 삽화처럼 한 이미지의 구도와 시각 요소가 모티프를 전달한다. 움직이는 장면의 연속이나 특정 소품 자체가 중심이면 이미지 하나에 한정하지 않는다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"이미지 단위","entry_url":"cards/ML-T00551/index.html"},{"id":"ML-T00552","row_version":2,"title":"소품 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"이야기 속 특정 물건이 반복되거나 상징적·기능적으로 의미를 더한다. 물건이 단순 배경 소품인지, 서사적 역할을 맡는지 확인해 적용한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"소품 단위","entry_url":"cards/ML-T00552/index.html"},{"id":"ML-T00553","row_version":3,"title":"행동 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"인물이나 행위자가 수행하는 개별 행동이 반복되거나 의미를 발생시킨다. 행동의 결과나 장면 전체보다 수행 동작 자체가 핵심인지 살핀다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"행동 단위","entry_url":"cards/ML-T00553/index.html"},{"id":"ML-T00554","row_version":4,"title":"장면 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"한 장소와 시간 안에서 이어지는 극적 상황이나 시각적 장면이 모티프의 핵심 범위다. 여러 장면에 걸친 전개나 편 전체의 구조를 설명할 때는 더 큰 단위를 적용한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"장면 단위","entry_url":"cards/ML-T00554/index.html"},{"id":"ML-T00555","row_version":4,"title":"시퀀스 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"여러 장면이 인과나 주제, 연출의 흐름으로 묶인 하나의 연속 구간에서 모티프가 작동한다. 단일 장면의 특징인지, 독립된 에피소드의 구성인지 구별한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"시퀀스 단위","entry_url":"cards/ML-T00555/index.html"},{"id":"ML-T00556","row_version":3,"title":"에피소드 단위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"한 회차나 독립된 에피소드 안에서 모티프가 전개되고 의미를 갖는다. 여러 회에 반복되는 요소라도 적용 범위가 해당 회차에 한정되는지 전체 시리즈에 걸치는지 명시한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"에피소드 단위","entry_url":"cards/ML-T00556/index.html"},{"id":"ML-T00557","row_version":2,"title":"작품 전체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"한 편의 완결된 작품 전체를 관통하는 구조나 반복 요소를 다룬다. 속편이나 다른 매체 작품까지 포함하지 않고 해당 작품의 범위 안에서 판단한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"작품 전체","entry_url":"cards/ML-T00557/index.html"},{"id":"ML-T00558","row_version":2,"title":"시리즈 전체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"여러 작품이나 회차로 이어지는 한 시리즈의 전반에 걸친 구성·반복을 가리킨다. 같은 세계를 공유한다는 사실만으로 한 시리즈로 묶지 않는다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"시리즈 전체","entry_url":"cards/ML-T00558/index.html"},{"id":"ML-T00559","row_version":2,"title":"세계관 전체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00548","tag_path":[],"summary":"작품이나 시리즈를 넘어 공통 규칙과 역사, 장소를 포함하는 허구 세계의 범위에서 작동한다. 한 작품의 설정을 세계 전체의 성질로 확대해 적용하지 않도록 한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"세계관 전체","entry_url":"cards/ML-T00559/index.html"},{"id":"ML-T00560","row_version":2,"title":"길이·지속","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"작품의 분량이나 전개가 지속되는 시간적 규모를 설명한다. 길이의 구체적 기준은 매체와 관습에 따라 달라질 수 있으므로 단순히 짧고 긴 인상만으로 하위 유형을 정하지 않는다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"길이·지속","entry_url":"cards/ML-T00560/index.html"},{"id":"ML-T00561","row_version":2,"title":"초단편","original":"Flash Fiction","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"한 문장부터 몇 쪽에 이르는 매우 짧은 분량 안에 인물과 사건, 인상을 압축해 담는 소설 형식이다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"초단편","entry_url":"cards/ML-T00561/index.html"},{"id":"ML-T00562","row_version":2,"title":"단편","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"비교적 짧은 분량 안에서 완결된 서사나 구성 단위를 이루는 형식이다. 매체별 관습을 고려하고, 연재물의 한 회차라는 이유만으로 단편이라 부르지 않는다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"단편","entry_url":"cards/ML-T00562/index.html"},{"id":"ML-T00563","row_version":2,"title":"중편","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"단편보다 넓은 전개 공간을 확보하면서 장편만큼 길게 확장되지 않는 중간 규모의 작품이다. 분량 기준은 분야마다 다르므로 단편과 장편 사이의 상대적 규모를 함께 본다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"중편","entry_url":"cards/ML-T00563/index.html"},{"id":"ML-T00564","row_version":2,"title":"장편","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"긴 분량을 활용해 여러 갈등이나 전개 단계를 축적하는 작품 형식이다. 작품이 여러 편으로 나뉘었는지가 아니라 각 작품의 분량과 완결 범위를 기준으로 판단한다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"장편","entry_url":"cards/ML-T00564/index.html"},{"id":"ML-T00565","row_version":2,"title":"미니시리즈","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"회차 수나 방영 기간을 제한해 계획된 이야기를 마무리하는 시리즈 형식이다. 단순히 현재 시즌이 짧다는 사실만으로는 미니시리즈라 보기 어렵다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"미니시리즈","entry_url":"cards/ML-T00565/index.html"},{"id":"ML-T00566","row_version":3,"title":"장기 시리즈","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"여러 회차나 작품을 장기간 이어 가며 서사와 인물 관계를 축적하는 시리즈다. 종료 시점이 정해져 있는지, 장기 연재·방영을 전제로 하는지 구분한다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"장기 시리즈","entry_url":"cards/ML-T00566/index.html"},{"id":"ML-T00567","row_version":2,"title":"지속 운영형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00560","tag_path":[],"summary":"정기적 갱신이나 이용자 참여를 통해 종료 시점을 고정하지 않고 계속 운영되는 형식이다. 이야기가 오래 이어진다는 사실만이 아니라 지속적인 콘텐츠 제공이나 서비스 운영이 있는지 본다.","accent":"#7E7970","tab":"#778F70","facet":"형식·구성·규모","bookmark":"지속 운영형","entry_url":"cards/ML-T00567/index.html"},{"id":"ML-T00568","row_version":3,"title":"연결 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"작품들이 서로 독립적인지, 서사나 세계를 어떤 방식으로 연결하는지 나타낸다. 연결 여부와 연결 방식은 별도로 판단해 단순한 주제 유사성을 연속성으로 간주하지 않는다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"연결 형식","entry_url":"cards/ML-T00568/index.html"},{"id":"ML-T00569","row_version":3,"title":"독립 작품","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"다른 작품을 알아야 이해할 핵심 정보 없이 자체적으로 완결되고 접근할 수 있는 작품이다. 후속작이나 같은 세계관의 작품이 존재해도 해당 편의 이해가 독립적이면 적용할 수 있다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"독립 작품","entry_url":"cards/ML-T00569/index.html"},{"id":"ML-T00570","row_version":3,"title":"연작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"공통 인물·주제·설정 등을 이어 여러 작품을 구성하는 형식이다. 각 편이 독립적으로 완결될 수 있으며, 앞선 편의 사건을 반드시 이어야 하는 연속극과 구분한다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"연작","entry_url":"cards/ML-T00570/index.html"},{"id":"ML-T00571","row_version":3,"title":"연속극","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"회차마다 이어지는 사건이나 인물 관계가 다음 회차의 이해와 전개에 누적되는 서사 형식이다. 공통 주제만 공유하거나 회차별로 완결되는 구성과 구별한다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"연속극","entry_url":"cards/ML-T00571/index.html"},{"id":"ML-T00572","row_version":3,"title":"옴니버스","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"서로 다른 이야기나 장면을 한 작품 안에 묶되 전체 배열이나 틀이 이들을 연결하는 형식이다. 각 이야기가 독립적이어도 하나의 작품 안에 편성된 구조인지 확인한다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"옴니버스","entry_url":"cards/ML-T00572/index.html"},{"id":"ML-T00573","row_version":3,"title":"앤솔러지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"공통 주제나 형식 아래 서로 독립된 작품들을 모아 제시하는 묶음이다. 작품 내부의 여러 에피소드를 배열한 옴니버스와 달리, 작품 단위의 선집일 수 있다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"앤솔러지","entry_url":"cards/ML-T00573/index.html"},{"id":"ML-T00574","row_version":4,"title":"프랜차이즈","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"하나의 브랜드나 지식재산을 중심으로 속편·각색·상품 등 여러 관련 작품과 사업을 묶는다. 작품 간 서사 연속성이나 세계관 공유가 프랜차이즈 성립의 필수 조건은 아니다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"프랜차이즈","entry_url":"cards/ML-T00574/index.html"},{"id":"ML-T00575","row_version":2,"title":"공유 세계관","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00568","tag_path":[],"summary":"서로 다른 작품들이 공통의 허구 세계와 규칙을 공유하는 연결 방식이다. 같은 브랜드나 제작 주체만 공유하는 경우와 실제 설정·역사·사건의 공통성을 구별한다.","accent":"#7E7970","tab":"#8B739C","facet":"형식·구성·규모","bookmark":"공유 세계관","entry_url":"cards/ML-T00575/index.html"},{"id":"ML-T00576","row_version":2,"title":"제시 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"정보와 사건을 어떤 문서나 발화의 형태로 독자에게 보여주는지 설명한다. 서술 내용의 사실성이나 장르와 혼동하지 말고 전달을 맡는 형식을 기준으로 삼는다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"제시 형식","entry_url":"cards/ML-T00576/index.html"},{"id":"ML-T00577","row_version":2,"title":"서간체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"편지나 이메일처럼 발신자와 수신자가 있는 서신을 통해 이야기를 제시한다. 서신이 장식적으로 삽입된 경우보다 서신의 내용과 배열이 서술을 실질적으로 이끄는지 본다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"서간체","entry_url":"cards/ML-T00577/index.html"},{"id":"ML-T00578","row_version":2,"title":"일기체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"날짜별 기록이나 개인의 일상적 기입을 통해 사건을 전달하는 형식이다. 날짜 표기만 있는 서술이 아니라 일기 기록의 시점과 성격이 제시 방식을 결정하는지 확인한다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"일기체","entry_url":"cards/ML-T00578/index.html"},{"id":"ML-T00579","row_version":2,"title":"기록물 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"보고서·기사·로그 등 기록물처럼 보이는 자료를 통해 정보를 전달한다. 문서의 외형만 빌렸는지, 기록의 축적과 신뢰성 문제가 서술에 실제로 작용하는지 구분한다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"기록물 형식","entry_url":"cards/ML-T00579/index.html"},{"id":"ML-T00580","row_version":3,"title":"인터뷰 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"질문과 답변, 발언자의 구분이 드러나는 인터뷰 내용을 중심으로 정보를 제시한다. 대화 장면을 옮긴 것인지, 인터뷰 절차와 응답이 구성의 틀인지 살핀다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"인터뷰 형식","entry_url":"cards/ML-T00580/index.html"},{"id":"ML-T00581","row_version":2,"title":"대본 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"인물명과 대사, 지문 등 공연·촬영을 위한 대본의 관습으로 내용을 제시한다. 대사 비중이 높다는 이유만으로 대본 형식이라 하지 않고 무대·화면 지시와 형식적 구성이 있는지 본다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"대본 형식","entry_url":"cards/ML-T00581/index.html"},{"id":"ML-T00582","row_version":2,"title":"채팅 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"메신저나 문자 대화의 화면과 발화 순서로 내용을 전달한다. 대화가 단순히 인용된 경우와 채팅 인터페이스나 메시지 교환이 작품의 주된 제시 구조인 경우를 구분한다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"채팅 형식","entry_url":"cards/ML-T00582/index.html"},{"id":"ML-T00583","row_version":2,"title":"문서 모음","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"여러 문서나 자료를 모아 배열하고, 그 관계에서 정보나 이야기를 드러내는 형식이다. 하나의 긴 기록물과 달리 서로 구별되는 자료들의 선택·배치가 의미 형성에 기여하는지 확인한다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"문서 모음","entry_url":"cards/ML-T00583/index.html"},{"id":"ML-T00584","row_version":2,"title":"백과사전 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00576","tag_path":[],"summary":"항목별 표제와 설명, 분류 체계로 지식을 정리하는 백과사전식 제시다. 단순히 설정 설명이 많은 작품이 아니라 항목 검색과 참조를 염두에 둔 배열인지 기준으로 삼는다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"백과사전 형식","entry_url":"cards/ML-T00584/index.html"},{"id":"ML-T00585","row_version":2,"title":"허구·기록 형식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"내용이 허구인지 실제 사실의 기록인지, 또는 두 방식을 어떻게 결합하는지 구분한다. 기록물처럼 보이는 연출과 실제 기록의 지위는 별개이므로 작품의 사실 주장과 제작 방식을 함께 본다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"허구·기록 형식","entry_url":"cards/ML-T00585/index.html"},{"id":"ML-T00586","row_version":4,"title":"픽션","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"인물·사건·세계가 창작된 허구 서사로 제시된다. 실제 장소나 역사적 소재를 사용하더라도 중심 사건을 창작했는지에 따라 논픽션과 구분한다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"픽션","entry_url":"cards/ML-T00586/index.html"},{"id":"ML-T00587","row_version":2,"title":"논픽션","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"실제 인물과 사건, 자료를 사실에 대한 설명이나 기록으로 제시하는 작업이다. 재연이나 극적 편집이 포함되어도 사실을 주장하는지, 창작된 서사인지 구분한다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"논픽션","entry_url":"cards/ML-T00587/index.html"},{"id":"ML-T00588","row_version":4,"title":"다큐멘터리","original":"Documentary","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"현실의 사람과 사건, 현상을 자료와 촬영으로 탐구하는 비허구 영상 형식이다. 취재와 편집의 관점이 설명의 방향을 만든다. 연속극이 다큐멘터리의 제작 관습을 한 회에 빌려오면 다큐멘터리 형식의 특별 회차이 된다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"다큐멘터리","entry_url":"cards/ML-T00588/index.html"},{"id":"ML-T00589","row_version":3,"title":"모큐멘터리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"허구의 사건이나 인물을 다큐멘터리의 인터뷰·관찰·증언 관습으로 연출하는 형식이다. 다큐멘터리처럼 보이는 화면만으로 판정하지 말고 허구적 설정과 사실 기록의 주장을 구별한다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"모큐멘터리","entry_url":"cards/ML-T00589/index.html"},{"id":"ML-T00590","row_version":3,"title":"파운드 푸티지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"작품 속 인물이나 제작자가 발견·촬영한 영상이라는 설정으로 제시되는 영상 형식이다. 흔들리는 카메라나 저화질 화면 자체가 아니라 영상의 출처가 서사 안에 설정되어 있는지가 기준이다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"파운드 푸티지","entry_url":"cards/ML-T00590/index.html"},{"id":"ML-T00591","row_version":3,"title":"다큐픽션","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00585","tag_path":[],"summary":"실제 기록과 허구적 장면·인물을 한 작품 안에서 결합해 제시한다. 단순한 재연이나 허구적 다큐 연출과 구별해 실제 자료와 창작 요소가 각각 어떤 역할을 하는지 살핀다.","accent":"#7E7970","tab":"#528982","facet":"형식·구성·규모","bookmark":"다큐픽션","entry_url":"cards/ML-T00591/index.html"},{"id":"ML-T00592","row_version":2,"title":"매체 구성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"작품이 하나의 매체로 이루어지는지, 여러 매체의 형식이나 기능을 결합하는지 설명한다. 매체 수와 작품 간 이동 방식은 서로 다른 기준이므로 따로 판단한다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"매체 구성","entry_url":"cards/ML-T00592/index.html"},{"id":"ML-T00593","row_version":3,"title":"단일 매체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00592","tag_path":[],"summary":"핵심 내용을 하나의 매체 형식으로 전달하는 구성이다. 한 매체 안에서 글과 그림, 음향이 함께 쓰이는 경우를 곧바로 복합 매체로 분류하지 말고 전달 체계의 결합 정도를 본다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"단일 매체","entry_url":"cards/ML-T00593/index.html"},{"id":"ML-T00594","row_version":2,"title":"복합 매체","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00592","tag_path":[],"summary":"하나의 작품 안에서 둘 이상의 매체 형식이나 표현 체계를 결합한다. 여러 매체로 각각 별도 작품이 나온 경우와 작품 내부의 결합을 구별한다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"복합 매체","entry_url":"cards/ML-T00594/index.html"},{"id":"ML-T00595","row_version":3,"title":"멀티미디어","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00592","tag_path":[],"summary":"영상·음향·문자·그래픽 등 복수의 표현 수단을 함께 사용해 내용을 전달한다. 매체 요소가 한 작품 안에 함께 있는지, 각 요소가 독립된 서사 작품을 이루는지 확인한다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"멀티미디어","entry_url":"cards/ML-T00595/index.html"},{"id":"ML-T00596","row_version":3,"title":"크로스미디어","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00592","tag_path":[],"summary":"하나의 이야기나 작품을 다른 매체로 옮기거나 재구성해 여러 매체에서 제시한다. 매체별 작품이 같은 핵심 내용을 반복하는지, 각 매체가 새로운 서사 정보를 보태는지 구분한다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"크로스미디어","entry_url":"cards/ML-T00596/index.html"},{"id":"ML-T00597","row_version":4,"title":"트랜스미디어","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00592","tag_path":[],"summary":"여러 매체의 작품이 하나의 큰 서사 세계를 나누어 확장하고, 각 매체가 고유한 정보를 제공한다. 같은 내용을 여러 형식으로 재현하는 크로스미디어와 달리 매체별 기여가 별개의 서사 조각인지 본다.","accent":"#7E7970","tab":"#7D8FA3","facet":"형식·구성·규모","bookmark":"트랜스미디어","entry_url":"cards/ML-T00597/index.html"},{"id":"ML-T00598","row_version":2,"title":"상호작용 정도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"이용자가 작품의 내용이나 진행에 어느 정도 영향을 미칠 수 있는지 나타낸다. 화면을 조작하거나 선택지를 누르는 행위만으로 상호작용 수준을 정하지 말고 결과가 콘텐츠에 미치는 범위를 살핀다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"상호작용 정도","entry_url":"cards/ML-T00598/index.html"},{"id":"ML-T00599","row_version":2,"title":"고정 제시형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"작품의 내용과 순서가 제작자가 정한 형태로 제시되고 이용자는 재생·열람 중심으로 받아들이는 방식이다. 일시정지나 재생 조작은 내용의 분기나 변화를 만들지 않으므로 서사적 상호작용과 구분한다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"고정 제시형","entry_url":"cards/ML-T00599/index.html"},{"id":"ML-T00600","row_version":2,"title":"선택형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"선택형 콘텐츠는 미리 마련된 여러 선택지 중 이용자가 하나를 골라 진행이나 결과를 정하는 방식이다. 선택이 이후 내용에 실질적 영향을 주는지, 단순히 순서나 표현만 바꾸는지 작품의 구조를 살펴 적용한다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"선택형","entry_url":"cards/ML-T00600/index.html"},{"id":"ML-T00601","row_version":2,"title":"분기형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"분기형 콘텐츠는 선택이나 조건에 따라 진행 경로가 갈라지고, 이후 서로 다른 장면이나 결과로 이어지는 구조다. 잠깐 다른 표현을 보여준 뒤 같은 경로로 합류하는 경우와 구분해, 경로 차이가 실제로 유지되는지 확인한다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"분기형","entry_url":"cards/ML-T00601/index.html"},{"id":"ML-T00602","row_version":3,"title":"생성형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"생성형 콘텐츠는 규칙과 재료를 바탕으로 실행 중에 장면·문장·음악·배치 등의 결과를 만들어내는 방식이다. 제작자가 완성한 변형안을 고르는 데 그치는지, 시스템이 조합하거나 산출하는지에 따라 판별한다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"생성형","entry_url":"cards/ML-T00602/index.html"},{"id":"ML-T00603","row_version":2,"title":"관객 참여형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"관객 참여형은 공연이나 상영 등 진행 중인 경험에 관객의 반응이나 행동이 들어가도록 설계한 형식이다. 관람 뒤의 감상·공유 활동이 아니라, 현장 참여가 진행이나 표현에 영향을 주는지를 기준으로 삼는다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"관객 참여형","entry_url":"cards/ML-T00603/index.html"},{"id":"ML-T00604","row_version":2,"title":"공동 창작형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00598","tag_path":[],"summary":"공동 창작형은 여러 참여자가 아이디어나 창작물을 보태고 조정해 하나의 결과물을 만드는 방식이다. 관객이 정해진 선택에 응답하는 것만으로는 해당하지 않으며, 창작 기여가 결과물에 반영되는지 살핀다.","accent":"#7E7970","tab":"#A07A87","facet":"형식·구성·규모","bookmark":"공동 창작형","entry_url":"cards/ML-T00604/index.html"},{"id":"ML-T00605","row_version":2,"title":"전달 시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"group","parent_id":"ML-F04","tag_path":[],"summary":"전달 시점은 콘텐츠가 이용자에게 제공되는 때와 참여가 가능한 시기의 관계를 가리킨다. 공개가 실시간인지 녹화본인지, 참여가 같은 시간에 이뤄져야 하는지와 공개 기간을 각각 구분해 적용한다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"전달 시점","entry_url":"cards/ML-T00605/index.html"},{"id":"ML-T00606","row_version":2,"title":"실시간 전달","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00605","tag_path":[],"summary":"실시간 전달은 공연·방송·게임 상황 등이 진행되는 동시에 이용자에게 전해지는 방식이다. 실시간으로 송출되더라도 이용자의 참여가 뒤늦게 가능할 수 있으므로, 전달과 참여의 시간 조건을 따로 확인한다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"실시간 전달","entry_url":"cards/ML-T00606/index.html"},{"id":"ML-T00607","row_version":2,"title":"녹화 전달","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00605","tag_path":[],"summary":"녹화 전달은 미리 기록한 영상이나 음성 등 콘텐츠를 이후에 재생해 제공하는 방식이다. 실시간 방송의 다시보기처럼 원래의 생방송과 재생본이 함께 제공되는 경우에는 어느 전달본을 설명하는지 구별한다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"녹화 전달","entry_url":"cards/ML-T00607/index.html"},{"id":"ML-T00608","row_version":2,"title":"동시 참여","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00605","tag_path":[],"summary":"동시 참여는 여러 이용자가 같은 시간대에 접속하거나 모여 함께 반응하고 활동하는 방식이다. 콘텐츠가 실시간으로 전달되는지만으로 판단하지 말고, 다른 참여자의 활동이 진행 중에 공유되거나 서로 영향을 주는지 확인한다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"동시 참여","entry_url":"cards/ML-T00608/index.html"},{"id":"ML-T00609","row_version":2,"title":"비동기 참여","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00605","tag_path":[],"summary":"비동기 참여는 참여자들이 서로 다른 시점에 행동해도 각자의 기여가 기록되거나 나중에 이어지는 방식이다. 각자 따로 이용하는 콘텐츠와 구분해, 시간차를 둔 참여가 공동 진행이나 결과에 연결되는지 살핀다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"비동기 참여","entry_url":"cards/ML-T00609/index.html"},{"id":"ML-T00610","row_version":2,"title":"기간 한정 공개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":"tag","parent_id":"ML-T00605","tag_path":[],"summary":"기간 한정 공개는 콘텐츠를 이용할 수 있는 기간을 정해 그 안에서만 접근하도록 제공하는 방식이다. 실시간으로 한 번 진행되는 행사와는 달리, 지정된 기간 동안 반복 이용이 가능한지와 종료 뒤 접근 여부를 기준으로 삼는다.","accent":"#7E7970","tab":"#79866C","facet":"형식·구성·규모","bookmark":"기간 한정 공개","entry_url":"cards/ML-T00610/index.html"},{"id":"ML-T00611","row_version":3,"title":"기본 진행","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"사건이 시작되어 변화와 결과에 이르는 이야기의 큰 진행 흐름을 가리킨다. 작품에 적용할 때는 개별 장면의 배열보다 전체 사건이 어떤 단계로 움직이는지 살핀다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"기본 진행","entry_url":"cards/ML-T00611/index.html"},{"id":"ML-T00612","row_version":3,"title":"발단","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"인물과 상황을 소개하고 이후 사건을 촉발하는 계기를 마련하는 초반 단계다. 배경 설명만 이어지는 부분이 아니라 핵심 갈등이나 변화의 조건이 놓이는지 기준으로 삼는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"발단","entry_url":"cards/ML-T00612/index.html"},{"id":"ML-T00613","row_version":3,"title":"전개","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"발단에서 제기된 갈등이 여러 사건과 선택을 거치며 복잡해지는 단계다. 사건 수가 많다는 이유만으로 전개라 보지 말고, 인물의 목표와 장애가 변하거나 누적되는지 본다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"전개","entry_url":"cards/ML-T00613/index.html"},{"id":"ML-T00614","row_version":3,"title":"위기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"갈등이 중대한 선택이나 불리한 상황에 몰려 해결 방향이 불확실해지는 국면이다. 긴장감이 높다는 사실만으로 절정과 같지 않으며, 결정적 대결이나 선택 직전의 압박인지 구분한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"위기","entry_url":"cards/ML-T00614/index.html"},{"id":"ML-T00615","row_version":3,"title":"절정","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"핵심 갈등이 가장 결정적인 선택이나 대결로 맞부딪혀 결과의 방향이 정해지는 지점이다. 작품의 가장 큰 볼거리나 감정적 고조와 반드시 일치하는 것은 아니며, 이후 사건을 바꾸는 결정성으로 판단한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"절정","entry_url":"cards/ML-T00615/index.html"},{"id":"ML-T00616","row_version":3,"title":"결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"주요 갈등의 결과와 그에 따른 인물·상황의 변화를 정리하는 이야기의 마무리다. 마지막 장면이나 최종 대사 자체보다 핵심 사건이 어떤 상태로 귀착되는지 살핀다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"결말","entry_url":"cards/ML-T00616/index.html"},{"id":"ML-T00617","row_version":3,"title":"후일담","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00611","tag_path":[],"summary":"핵심 갈등이 정리된 뒤 인물과 세계가 맞은 상태를 덧붙여 보여주는 짧은 마무리 부분이다. 결말의 해결 자체와 구별해, 해결 이후의 삶이나 여파를 제시하는지 본다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"후일담","entry_url":"cards/ML-T00617/index.html"},{"id":"ML-T00618","row_version":3,"title":"구성 모형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"이야기의 사건을 일정한 단계나 원리에 따라 배치해 설명하는 전체 설계 방식이다. 특정 작품이 몇 부분으로 나뉘는지만 세지 말고, 그 모형이 사건의 기능과 관계를 어떻게 묶는지 살핀다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"구성 모형","entry_url":"cards/ML-T00618/index.html"},{"id":"ML-T00619","row_version":2,"title":"3막 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"이야기를 설정과 진입, 대립의 심화, 해결의 세 큰 구간으로 조직하는 모형이다. 장면 수나 막의 물리적 구분이 아니라 각 구간이 목표 설정·충돌·귀결에서 맡는 역할로 판단한다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"3막 구조","entry_url":"cards/ML-T00619/index.html"},{"id":"ML-T00620","row_version":2,"title":"5막 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"이야기를 다섯 구간으로 나누어 상승과 하강을 포함한 극적 흐름을 구성하는 모형이다. 다섯 장이나 다섯 회차로 나뉘었다는 사실만으로 적용하지 말고, 각 구간의 극적 기능이 구별되는지 본다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"5막 구조","entry_url":"cards/ML-T00620/index.html"},{"id":"ML-T00621","row_version":3,"title":"기승전결","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"사건을 시작하고 키운 뒤 방향을 꺾어 마무리하는 네 부분의 전통적 구성 원리다. 단순히 네 장면이나 네 문단으로 나누는 것과 구별해, 전환부가 앞선 흐름을 새롭게 바꾸는지 살핀다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"기승전결","entry_url":"cards/ML-T00621/index.html"},{"id":"ML-T00622","row_version":4,"title":"영웅의 여정","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"주인공이 익숙한 세계를 떠나 시련과 조력자를 거치고 변화한 채 돌아오는 큰 여정형 서사 모형이다. 개별 시련이나 상징 하나가 아니라 전체 이야기의 단계와 귀환까지 이어지는 틀에 적용한다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"영웅의 여정","entry_url":"cards/ML-T00622/index.html"},{"id":"ML-T00623","row_version":3,"title":"탐색과 귀환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"인물이 익숙한 곳을 떠나 낯선 공간이나 과제를 통과한 뒤 출발점 또는 공동체로 돌아오는 이야기 흐름이다. 단순한 이동이나 귀가 장면과 달리, 여정의 경험이 귀환 후 인물이나 관계를 바꾸는지 본다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"탐색과 귀환","entry_url":"cards/ML-T00623/index.html"},{"id":"ML-T00624","row_version":5,"title":"성장 서사 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"주인공의 능력·판단·정체성이 경험을 통해 점차 달라지는 과정을 중심에 둔 서사 모형이다. 나이가 들거나 실력이 늘어나는 것만으로 보지 말고, 변화가 주요 사건의 인과와 결말에 연결되는지 판단한다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"성장 서사 구조","entry_url":"cards/ML-T00624/index.html"},{"id":"ML-T00625","row_version":3,"title":"흥망성쇠 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00618","tag_path":[],"summary":"인물이나 집단의 상승과 번영이 쇠퇴와 몰락으로 이어지는 흐름을 조직하는 모형이다. 성공 뒤에 실패가 한 번 일어나는 정도가 아니라, 흥성과 쇠퇴가 주요 사건의 연쇄를 이루는지 본다.","accent":"#6A748C","tab":"#778F70","facet":"서사 구조","bookmark":"흥망성쇠 구조","entry_url":"cards/ML-T00625/index.html"},{"id":"ML-T00626","row_version":3,"title":"시간 배열","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"이야기 속 사건이 일어난 순서와 관객·독자가 접하는 순서를 배열하는 방식이다. 시간대가 여러 개 등장하는지보다 그 시간대의 배치가 정보와 이해의 순서를 어떻게 만드는지 살핀다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"시간 배열","entry_url":"cards/ML-T00626/index.html"},{"id":"ML-T00627","row_version":3,"title":"순행 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"사건이 일어난 시간 순서에 가깝게 이야기를 제시하는 배열이다. 과거 회상이나 시간 생략이 일부 있다는 이유만으로 제외하지 말고, 전체 흐름이 대체로 앞에서 뒤로 진행하는지 본다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"순행 구조","entry_url":"cards/ML-T00627/index.html"},{"id":"ML-T00628","row_version":3,"title":"역순 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"이야기의 현재 지점에서 출발해 과거 사건을 거슬러 올라가며 정보를 제시하는 배열이다. 짧은 회상 한 장면과 구별해, 역방향 제시가 이야기의 주요 진행 원리가 되는지 판단한다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"역순 구조","entry_url":"cards/ML-T00628/index.html"},{"id":"ML-T00629","row_version":3,"title":"교차 시간 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"서로 다른 시기의 사건을 번갈아 제시해 시간대 사이의 관계를 드러내는 배열이다. 단순히 여러 시대가 등장하는 것과 달리, 장면 전환이 두 시간 흐름을 연결하거나 대비하는지 본다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"교차 시간 구조","entry_url":"cards/ML-T00629/index.html"},{"id":"ML-T00630","row_version":2,"title":"순환 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"이야기의 사건이나 상태가 일정한 간격을 두고 되풀이되어 처음과 끝이 구조적으로 맞물리는 방식이다. 반복되는 하루나 회차가 이야기 속에서 실제로 재현되는 시간 반복인지, 끝이 처음을 환기하는 형식적 순환인지 구분한다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"순환 구조","entry_url":"cards/ML-T00630/index.html"},{"id":"ML-T00631","row_version":3,"title":"시간 반복 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"같은 시간 구간이나 사건이 이야기 안에서 거듭 발생하고, 반복 때마다 정보나 조건이 달라지는 구조다. 회상이나 반복 장면의 재생과 구별해, 인물이나 세계가 반복 자체를 겪는지 본다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"시간 반복 구조","entry_url":"cards/ML-T00631/index.html"},{"id":"ML-T00632","row_version":3,"title":"비선형 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00626","tag_path":[],"summary":"사건의 시간 순서나 인과 흐름을 직선적으로 따르지 않고 여러 방식으로 재배치하는 구조다. 회상 한 번만으로 단정하지 말고, 시간·인과의 비직선적 배열이 작품의 이해에 지속적으로 작용하는지 살핀다.","accent":"#6A748C","tab":"#8B739C","facet":"서사 구조","bookmark":"비선형 구조","entry_url":"cards/ML-T00632/index.html"},{"id":"ML-T00633","row_version":4,"title":"서사 줄기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"group","parent_id":"ML-F05","tag_path":[],"summary":"작품을 이끄는 주요 사건의 인과적 흐름, 즉 중심 이야기의 가닥을 뜻한다. 등장인물이나 장소가 여러 개라는 사실과 구별해, 어떤 사건 연결이 서사의 중심을 이루는지 본다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"서사 줄기","entry_url":"cards/ML-T00633/index.html"},{"id":"ML-T00634","row_version":4,"title":"단일 플롯","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"하나의 중심 목표나 갈등을 따라 주요 사건이 이어지는 이야기 구성이다. 주인공이 한 명이라는 조건은 아니며, 별도 사건 가닥들이 독립적인 중심 줄기로 병행하는지에 따라 다중 플롯과 구별한다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"단일 플롯","entry_url":"cards/ML-T00634/index.html"},{"id":"ML-T00635","row_version":3,"title":"다중 플롯","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"서로 구별되는 둘 이상의 주요 사건 가닥이 한 작품 안에서 진행되는 구성이다. 등장인물이나 장소가 많아도 모두 같은 중심 갈등에 종속된다면 다중 플롯으로 보지 않는다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"다중 플롯","entry_url":"cards/ML-T00635/index.html"},{"id":"ML-T00636","row_version":3,"title":"병렬 서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"서로 독립된 사건 흐름을 나란히 이어가며 각각의 진행을 보여주는 구성이다. 장면이 번갈아 나온다는 사실만으로는 부족하며, 흐름들이 한동안 별도 인과와 목표를 유지하는지 본다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"병렬 서사","entry_url":"cards/ML-T00636/index.html"},{"id":"ML-T00637","row_version":3,"title":"교차 서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"둘 이상의 사건 흐름을 번갈아 오가며 관계나 대비를 드러내는 구성이다. 단지 시간대가 교대로 제시되는 배열과 구별해, 각 흐름이 별도의 사건 가닥으로 전개되는지 살핀다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"교차 서사","entry_url":"cards/ML-T00637/index.html"},{"id":"ML-T00638","row_version":3,"title":"액자 서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":"tag","parent_id":"ML-T00633","tag_path":[],"summary":"바깥 이야기 안에 인물이 들려주거나 기록한 안쪽 이야기를 넣어 층위를 만드는 구성이다. 회상이나 과거 장면이 있다는 것만으로는 해당하지 않으며, 이야기를 전달하는 틀이 안쪽 서사를 감싸는지 본다.","accent":"#6A748C","tab":"#A58A4E","facet":"서사 구조","bookmark":"액자 서사","entry_url":"cards/ML-T00638/index.html"}]}.cards;